import Badge from './Badge'

const roles: Record<string, AriaLiveRole | undefined> = {
  None: undefined,
  'AriaLiveRole.Alert': AriaLiveRole.Alert,
  'AriaLiveRole.Status': AriaLiveRole.Status,
  'AriaLiveRole.Presentation': AriaLiveRole.Presentation,
}

export default {
  title: 'Components/Badge',
  component: Badge,
  argTypes: {
    'aria-label': {
      table: {
        category: 'Accessibility',
      },
    },
    color: {
      table: {
        category: 'Appearance',
      },
    },
    invisible: {
      table: {
        category: 'Appearance',
      },
    },
    max: {
      table: {
        category: 'Appearance',
      },
    },
    overlap: {
      table: {
        category: 'Appearance',
      },
    },
    position: {
      control: { type: 'object' },
      table: {
        category: 'Appearance',
      },
    },
    role: {
      control: { type: 'select' },
      options: [...Object.keys(roles)],
      mapping: roles,
      table: {
        category: 'Accessibility',
      },
    },
    showZero: {
      table: {
        category: 'Appearance',
      },
    },
    value: {
      table: {
        category: 'Content',
      },
    },
    variant: {
      table: {
        category: 'Appearance',
      },
    },
  },
  args: {
    color: 'default',
    invisible: false,
    max: 99,
    overlap: 'rectangle',
    position: { x: 'right', y: 'top' },
    showZero: false,
    value: 1,
    variant: 'default',
  },
}

function Template(args: BadgeProps & { role: string }): JSX.Element {
  const [invisible, setInvisible] = useState(false)

  const toggleInvisible = () => {
    setInvisible((prevState) => !prevState)
  }

  // The type error is due to controls potentially passing an aria-label with role presentation
  return (
    <Badge {...args} invisible={args.invisible || invisible}>
      {args.overlap === 'circle' ? (
        <button className="focus:outline-none" onClick={toggleInvisible}>
          <Avatar color="indigo">
            <Person />
          </Avatar>
        </button>
      ) : (
        <Button onClick={toggleInvisible}>Toggle Badge</Button>
      )}
    </Badge>
  )
}

export const Default = {
  render: Template,
}

