export function Visibility(): JSX.Element {
  const [visible, setVisible] = useState(true)
  const [showZero, setShowZero] = useState(false)
  const [value, setValue] = useState(1)

  const toggleVisible = () => {
    setVisible((prevState) => !prevState)
  }

  const toggleShowZero = () => {
    setShowZero((prevState) => !prevState)
  }

  const toggleValue = () => {
    setValue((prevState) => (prevState === 0 ? 1 : 0))
  }

  return (
    <div className="flex flex-col gap-4">
      <Badge
        color="error"
        invisible={!visible}
        showZero={showZero}
        value={value}
      >
        <span className="w-8 h-8 text-black-60">
          <Chat />
        </span>
      </Badge>

      <div className="flex flex-row gap-4">
        <Button onClick={toggleVisible}>
          {visible ? 'Hide badge' : 'Show badge'}
        </Button>
        <Button onClick={toggleShowZero}>
          {showZero ? 'Hide zero' : 'Show zero'}
        </Button>
        <Button onClick={toggleValue}>
          {value === 0 ? 'Reset value' : 'Set to 0'}
        </Button>
      </div>
    </div>
  )
}

